export const trailBadgesScript = "/** Original route identifiers; not official agency/association insignia. */\nfunction installTrailBadges(map) {\n    const colors = { PCT: '#296a91', AT: '#415d3c', CDT: '#8c553b', JMT: '#745b3e', TRT: '#775595', PNT: '#745b3e', AZT: '#745b3e', FT: '#745b3e', IAT: '#745b3e', NCT: '#745b3e', NET: '#745b3e', PHT: '#745b3e', NTT: '#745b3e' };\n    function add(ref) {\n        const id = 'trail-' + ref;\n        if (!colors[ref] || map.hasImage(id))\n            return;\n        const canvas = document.createElement('canvas');\n        canvas.width = 80;\n        canvas.height = 80;\n        const ctx = canvas.getContext('2d');\n        ctx.beginPath();\n        ctx.moveTo(20, 3);\n        ctx.lineTo(60, 3);\n        ctx.quadraticCurveTo(77, 3, 77, 20);\n        ctx.lineTo(77, 60);\n        ctx.quadraticCurveTo(77, 77, 60, 77);\n        ctx.lineTo(20, 77);\n        ctx.quadraticCurveTo(3, 77, 3, 60);\n        ctx.lineTo(3, 20);\n        ctx.quadraticCurveTo(3, 3, 20, 3);\n        ctx.closePath();\n        ctx.fillStyle = '#fffdf4';\n        ctx.fill();\n        ctx.strokeStyle = colors[ref];\n        ctx.lineWidth = 5;\n        ctx.stroke();\n        ctx.lineWidth = 3;\n        ctx.beginPath();\n        ctx.moveTo(16, 27);\n        ctx.lineTo(64, 27);\n        ctx.stroke();\n        ctx.fillStyle = colors[ref];\n        ctx.font = 'bold 27px Arial,sans-serif';\n        ctx.textAlign = 'center';\n        ctx.fillText(ref, 40, 56);\n        map.addImage(id, ctx.getImageData(0, 0, 80, 80), { pixelRatio: 3 });\n    }\n    map.on('styleimagemissing', (event) => { if (event.id.startsWith('trail-'))\n        add(event.id.slice(6)); });\n    map.on('styledata', () => { if (map.isStyleLoaded())\n        for (const ref of Object.keys(colors))\n            add(ref); });\n    if (map.isStyleLoaded())\n        for (const ref of Object.keys(colors))\n            add(ref);\n}\n";
